.UID .cap{transform-origin:center;animation:UID_drop .6s cubic-bezier(.2,1.3,.3,1) .35s both}
.UID .body{transform-origin:50% 100%;animation:UID_up .7s cubic-bezier(.2,1.3,.3,1) .45s both}
.UID .foot{transform-origin:center;animation:UID_up .6s cubic-bezier(.2,1.3,.3,1) .62s both}
.UID .inner{animation:UID_fade .6s ease .82s both}
.UID .moon{transform-origin:center;animation:UID_flyR .7s cubic-bezier(.2,1.3,.3,1) .55s both,UID_twk 3s ease-in-out 1.5s infinite}
.UID .heart{transform-origin:center;animation:UID_pop .6s cubic-bezier(.2,1.3,.3,1) .95s both,UID_beat 2.6s ease-in-out 1.7s infinite}
.UID .spark{transform-origin:center}
.UID .s1{animation:UID_pop .5s cubic-bezier(.2,1.3,.3,1) 1s both,UID_tw 2.1s ease-in-out 1.6s infinite}
.UID .s2{animation:UID_pop .5s cubic-bezier(.2,1.3,.3,1) 1.15s both,UID_tw 2.4s ease-in-out 1.8s infinite}
.UID .s3{animation:UID_pop .5s cubic-bezier(.2,1.3,.3,1) 1.3s both,UID_tw 2s ease-in-out 2s infinite}
.UID .s4{animation:UID_pop .5s cubic-bezier(.2,1.3,.3,1) 1.45s both,UID_tw 2.6s ease-in-out 2.2s infinite}
@keyframes UID_halo{0%{opacity:0;transform:scale(.5)}100%{opacity:.5;transform:scale(1)}}
@keyframes UID_pulse{0%,100%{opacity:.38;transform:scale(1)}50%{opacity:.62;transform:scale(1.1)}}
@keyframes UID_draw{to{stroke-dashoffset:0}}
@keyframes UID_pop{0%{opacity:0;transform:scale(0)}100%{opacity:1;transform:scale(1)}}
@keyframes UID_drop{0%{opacity:0;transform:translateY(-26px)}100%{opacity:1;transform:translateY(0)}}
@keyframes UID_up{0%{opacity:0;transform:translateY(34px) scale(.72)}100%{opacity:1;transform:translateY(0) scale(1)}}
@keyframes UID_fade{0%{opacity:0}100%{opacity:.3}}
@keyframes UID_flyR{0%{opacity:0;transform:translateX(28px) rotate(34deg)}100%{opacity:1;transform:translateX(0) rotate(0)}}
@keyframes UID_twk{0%,100%{opacity:1}50%{opacity:.68}}
@keyframes UID_beat{0%,100%{transform:scale(1)}50%{transform:scale(1.13)}}
@keyframes UID_tw{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.5;transform:scale(.65)}}

ouia-cafe.css:
.UID .glow{transform-origin:center;animation:UID_glow 3.6s ease-in-out infinite}
.UID .base{animation:UID_rise .7s cubic-bezier(.2,1.3,.3,1) .05s both}
.UID .carafe{animation:UID_rise .78s cubic-bezier(.2,1.3,.3,1) .18s both}
.UID .dripper{animation:UID_drop .78s cubic-bezier(.2,1.3,.3,1) .48s both}
.UID .bed{transform-origin:center;animation:UID_pop .5s cubic-bezier(.2,1.3,.3,1) 1s both}
.UID .ridge{transform-origin:center;animation:UID_pop .5s cubic-bezier(.2,1.3,.3,1) 1.12s both}
.UID .steam{stroke-dasharray:64;transform-origin:bottom center;animation:UID_draw .8s ease-out .9s both,UID_drift 4.4s ease-in-out 1.75s infinite}
.UID .s2{animation-delay:1.05s,2.2s}
.UID .drip{transform-origin:top center;animation:UID_drip 2.5s ease-in 1.7s infinite}
@keyframes UID_rise{from{opacity:0;transform:translateY(34px)}to{opacity:1;transform:translateY(0)}}
@keyframes UID_drop{from{opacity:0;transform:translateY(-40px)}to{opacity:1;transform:translateY(0)}}
@keyframes UID_pop{0%{opacity:0;transform:scale(.4)}100%{opacity:1;transform:scale(1)}}
@keyframes UID_glow{0%,100%{opacity:.14;transform:scale(.9)}50%{opacity:.3;transform:scale(1.07)}}
@keyframes UID_draw{from{stroke-dashoffset:64}to{stroke-dashoffset:0}}
@keyframes UID_drift{0%{opacity:.35;transform:translate(-1px,2px)}50%{opacity:.9;transform:translate(1px,-3px)}100%{opacity:.35;transform:translate(-1px,2px)}}
@keyframes UID_drip{0%{opacity:0;transform:translateY(-2px)}18%{opacity:1}68%{opacity:1;transform:translateY(9px)}80%{opacity:0;transform:translateY(9px)}100%{opacity:0}}
